\begin{equation}    \label{eq1.22a}
    r_\lambda(\xi,\eta) = \sum_{k=1}^n \onel(\xi)\,\frac{e^{-\ensuremath\sqrt{2\gl}\,d(\xi,\eta)}}{\ensuremath\sqrt{2\gl}}\,\onel(\eta),
\end{equation}
and
\begin{equation}    \label{eq1.22b}
\begin{split}
    r_{v,\lambda}(\xi,\eta)
        &= \sum_{k=1}^n \onel(\xi)\, \frac{e^{-\ensuremath\sqrt{2\gl}\, d_v(\xi,\eta)}}{\ensuremath\sqrt{2\gl}}\,\onel(\eta)\\[1ex]
        &= \sum_{k=1}^n \onel(\xi)\, \frac{1}{\ensuremath\sqrt{2\gl}}\,e_\lambda(\xi)\, e_\lambda(\eta)\,\onel(\eta).
\end{split}
\end{equation}
In particular, $r^D_\lambda$ is the Laplace transform of the Dirichlet heat
kernel~\eqref{eq1.20} at $\lambda>0$.

By construction, the last expectation value is equal to
\begin{equation*}
    \beta\int_0^\infty e^{-\beta s}\int_0^\infty e^{-\lambda t}
        E_\xi\Bigl(e^{-\lambda K_s}\,f\bigl(X_{t+K_s}\bigr)\Bigr)\,dt\,ds,
\end{equation*}
where we used Fubini's theorem. Consider the expectation value under the integrals,
and recall that for fixed $s\in\mathbb{R}_+$, $K_s$ is an $\mathcal{F}$--stopping time, while
$X$ is strongly Markovian relative to $\mathcal{F}$. Hence we can compute as follows
\begin{align*}
    E_\xi\Bigl(e^{-\lambda K_s}\,f\bigl(X_{t+K_s}\bigr)\Bigr)
        &= E_\xi\Bigl(e^{-\lambda K_s}\,E_\xi\Bigl(f\bigl(X_{t+K_s}\bigr)\ensuremath\,\big|\, \mathcal{F}_{K_s}\Bigr)\Bigr)\\
        &= E_\xi\Bigl(e^{-\lambda K_s}\,E_{X(K_s)}\bigl(f(X_t)\bigr)\Bigr)\\
        &= E_\xi\bigl(e^{-\lambda K_s}\bigr)\,E_v\bigl(f(X_t)\bigr),
\end{align*}
where we used the fact that a.s.\ $X(K_s)=v$. So far we have established
\begin{equation*}
    \ensuremath{\hat R}_\lambda f(\xi) = R_\lambda f(\xi) - \ensuremath{\hat E}_\xi\bigl(e^{-\lambda \zeta_\beta}\bigr)\,R_\lambda f(v).
\end{equation*}
In order to compute the expectation value on the right hand side, we first remark
that because $L$ is zero until $X$ hits the vertex for the first time, we find
that for given $s\in\mathbb{R}_+$, $K_s\ge H_v$, and therefore $K_s = H_v + K_s\comp \theta_{H_v}$.
Hence, and again by the strong Markov property,
\begin{align*}
    E_\xi\bigl(e^{-\lambda K_s}\bigr)
        &= E_\xi\bigl(e^{-\lambda H_v}\,e^{-\lambda K_s\comp H_v}\bigr)\\
        &= E_\xi\bigl(e^{-\lambda H_v}\,E_\xi\bigl(e^{-\lambda K_s\comp H_v}\ensuremath\,\big|\, \mathcal{F}_{H_v}\bigr)\bigr)\\
        &= E_\xi\bigl(e^{-\lambda H_v}\bigr) E_v\bigl(e^{-\lambda K_s}\bigr),
\end{align*}
Integrating the last identity against the exponential law in the variable $s$, we
find with formula~\eqref{eq1.14}
\begin{equation*}
    \ensuremath{\hat E}_\xi\bigl(e^{-\lambda\zeta_\beta}\bigr) = e_\lambda(\xi)\,\ensuremath{\hat E}_v\bigl(e^{-\lambda \zeta_\beta}\bigr),
\end{equation*}
and the proof is finished.
\end{proof}

Hence we find for the resolvent $\ensuremath R^w$ of the Walsh process
\begin{subequations}    \label{eq2.3}
\begin{equation}    \label{eq2.3a}
