Let $K^B = (K^B_r,\,r\ge 0)$ denote the right continuous pseudo-inverse of $L$,
\begin{equation}    \label{eq1.11}
    K^B_r = \inf\bigl\{t\ge 0,\,L^B_t>r\bigr\},\qquad r\ge 0.
\end{equation}
Note that due to the a.s.\ continuity of $L^B$ we have a.s.\ $L^B_{K_r} = r$. In
appendix~B of~\cite{BMMG0} the present authors proved the following

\begin{proof}
For $\lambda>0$, $f\in B(\mathcal{G})$, $\xi\in\mathcal{G}$
\begin{align*}
    \ensuremath{\hat R}_\lambda f(\xi)
        &= \ensuremath{\hat E}_\xi\Bigl(\int_0^{\zeta_\beta} e^{-\lambda t} f(X_t)\,dt\Bigr)\\
        &= R_\lambda f(\xi) - \ensuremath{\hat E}_\xi\Bigl(e^{-\lambda\zeta_\beta} \int_0^\infty
                e^{-\lambda t}\,f\bigl(X_{t+\zeta_\beta}\bigr)\,dt\Bigr).
\end{align*}
By construction, the last expectation value is equal to
\begin{equation*}
    \beta\int_0^\infty e^{-\beta s}\int_0^\infty e^{-\lambda t}
        E_\xi\Bigl(e^{-\lambda K_s}\,f\bigl(X_{t+K_s}\bigr)\Bigr)\,dt\,ds,
\end{equation*}
where we used Fubini's theorem. Consider the expectation value under the integrals,
and recall that for fixed $s\in\mathbb{R}_+$, $K_s$ is an $\mathcal{F}$--stopping time, while
$X$ is strongly Markovian relative to $\mathcal{F}$. Hence we can compute as follows
\begin{align*}
    E_\xi\Bigl(e^{-\lambda K_s}\,f\bigl(X_{t+K_s}\bigr)\Bigr)
        &= E_\xi\Bigl(e^{-\lambda K_s}\,E_\xi\Bigl(f\bigl(X_{t+K_s}\bigr)\ensuremath\,\big|\, \mathcal{F}_{K_s}\Bigr)\Bigr)\\
        &= E_\xi\Bigl(e^{-\lambda K_s}\,E_{X(K_s)}\bigl(f(X_t)\bigr)\Bigr)\\
        &= E_\xi\bigl(e^{-\lambda K_s}\bigr)\,E_v\bigl(f(X_t)\bigr),
\end{align*}
where we used the fact that a.s.\ $X(K_s)=v$. So far we have established
\begin{equation*}
    \ensuremath{\hat R}_\lambda f(\xi) = R_\lambda f(\xi) - \ensuremath{\hat E}_\xi\bigl(e^{-\lambda \zeta_\beta}\bigr)\,R_\lambda f(v).
\end{equation*}
In order to compute the expectation value on the right hand side, we first remark
that because $L$ is zero until $X$ hits the vertex for the first time, we find
that for given $s\in\mathbb{R}_+$, $K_s\ge H_v$, and therefore $K_s = H_v + K_s\comp \theta_{H_v}$.
Hence, and again by the strong Markov property,
\begin{align*}
    E_\xi\bigl(e^{-\lambda K_s}\bigr)
        &= E_\xi\bigl(e^{-\lambda H_v}\,e^{-\lambda K_s\comp H_v}\bigr)\\
        &= E_\xi\bigl(e^{-\lambda H_v}\,E_\xi\bigl(e^{-\lambda K_s\comp H_v}\ensuremath\,\big|\, \mathcal{F}_{H_v}\bigr)\bigr)\\
        &= E_\xi\bigl(e^{-\lambda H_v}\bigr) E_v\bigl(e^{-\lambda K_s}\bigr),
\end{align*}
Integrating the last identity against the exponential law in the variable $s$, we
find with formula~\eqref{eq1.14}
\begin{equation*}
    \ensuremath{\hat E}_\xi\bigl(e^{-\lambda\zeta_\beta}\bigr) = e_\lambda(\xi)\,\ensuremath{\hat E}_v\bigl(e^{-\lambda \zeta_\beta}\bigr),
\end{equation*}
and the proof is finished.
\end{proof}

\begin{remark}  \label{rem1.7}
Formula~\eqref{eq1.30} is quite useful, because if the resolvent of $X$ is known, then
--- in view of equation~\eqref{eq1.14} --- it reduces the calculation of $\ensuremath{\hat R}_\lambda$
to the computation of the Laplace transform of the density of $\zeta_\beta$ under
$\ensuremath{\hat P}_v$.
\end{remark}

\begin{proof}
Since by construction $W$ has infinite lifetime, $\ensuremath H^w_{v,\epsilon}$ is the hitting time
of the set of the $n$ points with local coordinates $(k,\epsilon)$, $\ensuremath k=1,\dotsc,n$. Therefore, by the
independence of the choice of the edge for the values of the excursion, it follows
that under $P_v$ the stopping time $\ensuremath H^w_{v,\epsilon}$ has the same law as the hitting
time of the point $\epsilon>0$ of a reflected Brownian motion on $\mathbb{R}_+$, starting at
$0$. Thus the statement of the lemma follows from equation~\eqref{eq1.6}.
\end{proof}

From the construction of $W$ we immediately get
\begin{equation*}
    E_v\Bigl(f\bigl(W(\ensuremath H^w_{v,\epsilon})\bigr)\Bigr) = \sum_{k=1}^n w_k f_k(\epsilon),
\end{equation*}
with the notation $f_k(x)=f(k,x)$, $x\in\mathbb{R}_+$. Inserting this into
equation~\eqref{eq2.1} we obtain
\begin{equation*}
    A^w f(v) = \lim_{\epsilon\ensuremath\downarrow 0} \epsilon^{-2} \sum_{k=1}^n w_k \bigl(f_k(\epsilon)-f(v)\bigr),
\end{equation*}
and since $f'(v_k)$ exists (cf.\ lemma~\ref{lemC02}) it is obvious that
this entails the condition
\begin{equation}    \label{eq2.2}
    \sum_{k=1}^n w_k f'(v_k) = 0.
\end{equation}
For later use we record this result as

For the remainder of this section we make the choice $a=c=0$,
$w_k=b_k$, $k\in\ensuremath\{1,2,\dotsc,n\}$ in~\eqref{eq1.1}.

Next we compute the resolvent of $W$. Let $\lambda>0$, $f\in\ensuremath C_0(\cG)$, and consider first
$\xi=v$. Without loss of generality, we may assume that $W$ has been constructed pathwise
from a standard Brownian motion $B$ as described above, and that $B$ is as in
subsection~\ref{ssect1.2}. Then we get
\begin{equation*}
    E_v\bigl(f(W_t)\bigr)
        = \sum_{m=1}^n b_m E^Q_0\bigl(f_m(|B_t|)\bigr).
\end{equation*}
Hence we find for the resolvent $\ensuremath R^w$ of the Walsh process
\begin{subequations}    \label{eq2.3}
\begin{equation}    \label{eq2.3a}
    \ensuremath R^w_\lambda f(v)
        = \int_\mathcal{G} \ensuremath r^w_\lambda(v,\eta)\, f(\eta)\,d\eta
\end{equation}
with resolvent kernel $\ensuremath r^w_\lambda (v,\eta)$, $\eta\in\mathcal{G}$, given by
\begin{equation}    \label{eq2.3b}
    \ensuremath r^w_\lambda(v,\eta) = \sum_{m=1}^n 2 b_m\, \frac{e^{-\ensuremath\sqrt{2\gl}\, d(v,\eta)}}{\ensuremath\sqrt{2\gl}}\,\onel[m](\eta),
\end{equation}
\end{subequations}
and where the integration in~\eqref{eq2.3a} is with respect to the Lebesgue
measure on $\mathcal{G}$.

Now let $\xi\in\mathcal{G}$. We use the first passage time formula~\eqref{eq1.23} together with
formulae~\eqref{eq1.14} and \eqref{eq2.3}, and obtain

\begin{remark}  \label{rem2.6}
Alternatively $\ensuremath p^w(t,\xi,\eta)$ can also be written as
\begin{equation}    \label{eq2.9}
\begin{split}
    \ensuremath p^w(t,\xi,\eta)
        &= p(t,\xi,\eta)\\
        &\  + \sum_{k,m=1}^n \onel(\xi)
            \int_0^t P_\xi(H_v\in ds)\, \ensuremath S^w_{km}\, g\bigl(t-s,d(v,\eta)\bigr)\,\onel[m](\eta).
\end{split}
\end{equation}
Even though this formula appears somewhat more complicated than~\eqref{eq2.8}, it
exhibits the role of the scattering matrix $\ensuremath S^w$, that is, it describes more clearly what
happens when the process hits the vertex.
\end{remark}

\begin{proof}
We may consider the Walsh process $W$ as being pathwise constructed from a standard
Brownian motion $B$ on the real line as in the previous section, and we shall use
the notations and conventions from there. Then it is clear that under $P_v$ and
under $\ensuremath{\hat P}_v$, $\ensuremath H^w_{v,\epsilon}$ has the same law as the hitting time of the point
$\epsilon$ in $\mathbb{R}_+$ by the reflecting Brownian motion $|B|$ under $Q_0$, that is, as
$H^B_{\{-\epsilon,\epsilon\}}$ of the Brownian motion $B$ itself under $Q_0$. Let $K^w$ denote
the right continuous pseudo-inverse of $L^w$. For fixed $s\in\mathbb{R}_+$ we get
\begin{equation*}
    \{K^w_s < \ensuremath H^w_{v,\epsilon}\} = \{L^w(\ensuremath H^w_{v,\epsilon})>s\}.
\end{equation*}
Hence
\begin{align*}
    P_v\bigl(K^w_s < \ensuremath H^w_{v,\epsilon}\bigr)
        &= P_v\bigl(L^w(\ensuremath H^w_{v,\epsilon})>s\bigr)\\
        &= Q_0\bigl(L^B(H^B_{\{-\epsilon,\epsilon\}})>s\bigr).
\end{align*}
In appendix~B of~\cite{BMMG0} is shown with the method
in~\cite[Section~6.4]{KaSh91} that under $Q_0$ the random variable
$L^B(H^B_{\{-\epsilon,\epsilon\}})$ is exponentially distributed with mean $\epsilon$. So we find
\begin{equation*}
    P_v\bigl(K^w_s < \ensuremath H^w_{v,\epsilon}\bigr) = e^{-s/\epsilon}.
\end{equation*}
We integrate this relation against the exponential law with rate $\beta$ in the variable $s$,
and obtain
\begin{align*}
    \ensuremath{\hat P}_v\bigl(\zeta_{\beta,0}>\ensuremath H^w_{v,\epsilon}\bigr)
        &= 1 - \beta\int_0^\infty e^{-\beta s}\,P_v\bigl(K^W_s < \ensuremath H^w_{v,\epsilon}\bigr)\,ds\\
        &= \frac{1}{1+\epsilon\beta}.
\end{align*}
We used the fact that due to the continuity of the paths of $W$ we have
$\zeta_{\beta,0}\ne \ensuremath H^w_{v,\epsilon}$.
\end{proof}

We insert formula~\eqref{eq3.2} into equation~\eqref{eq3.1a}, and obtain
\begin{align*}
    A^e f(v)
        &=  \lim_{\epsilon\ensuremath\downarrow 0}\, \frac{1}{\ensuremath{\hat E}_v(\ensuremath H^e_{v,\epsilon})}
                \,\Bigr(\ensuremath{\hat E}_v\Bigl(f\bigl(\ensuremath W^e(\ensuremath H^e_{v,\epsilon})\bigr)\Bigr) - f(v)\Bigl)\\
        &=  \lim_{\epsilon\ensuremath\downarrow 0}\, \frac{1}{\ensuremath{\hat E}_v(\ensuremath H^e_{v,\epsilon})}
                \,\Bigl(\frac{1}{1+\epsilon\beta}\,\sum_{k=1}^n w_k f_k(\epsilon) - f(v)\Bigr)\\
        &=  \lim_{\epsilon\ensuremath\downarrow 0}\, \frac{\epsilon}{\ensuremath{\hat E}_v(\ensuremath H^e_{v,\epsilon})}
                \frac{1}{1+\epsilon\beta}\,\Bigl(\sum_{k=1}^n w_k\,\frac{f_k(\epsilon)-f(v)}{\epsilon}
                    -\beta f(v)\Bigr).
\end{align*}
Obviously $\ensuremath{\hat E}_v(\ensuremath H^e_{v,\epsilon})\le E_v(\ensuremath H^w_{v,\epsilon})=\epsilon^2$ (cf.~lemma~\ref{lem2.1}).
Since the last limit and $f'(v_k)$, $k\in\ensuremath\{1,2,\dotsc,n\}$, exist and are finite, we get as a necessary
condition
\begin{equation}    \label{eq3.3}
    \sum_{k=1}^n w_k f'(v_k) - \beta f(v) =0.
\end{equation}
Thus we have proved the following theorem.

\begin{remark}  \label{rem3.5}
Note that in contrast to the case of the Walsh process, this time the scattering
matrix is not constant with respect to $\lambda>0$. Also, when $\beta=0$,
formula~\eqref{eq2.4c} is recovered, as it should be. In analogy with the discussion
in remark~\ref{rem2.4}, the boundary conditions for the elastic Walsh process is
given by the matrices
\begin{equation*}
    A^e = \begin{pmatrix}
             0&0&0&\ldots&0&\beta\\
             1&-1&0&\ldots&0&0\\
             0&1&-1&\ldots&0&0\\
             0&0&1&\ldots &0&0\\
             \vdots&\vdots&\vdots&\ddots&\vdots&\vdots\\
             0&0&0&\ldots&1&-1
         \end{pmatrix},\ 
    B^e=\begin{pmatrix}
            w_1&w_2&w_3&\ldots&w_{n-1}&w_n\\
            0&0&0&\ldots&0&0\\
            0&0&0&\ldots&0&0\\
            0&0&0&\ldots&0&0\\
            \vdots&\vdots&\vdots&\ddots&\vdots&\vdots\\
            0&0&0&\ldots&0&0
        \end{pmatrix},
\end{equation*}
such that
\begin{align*}
    \ensuremath S^e(\lambda) &= S_{A^e,B^e}(E=-2\lambda)\\
              &= - (A^e+\ensuremath\sqrt{2\gl} B^e)^{-1}\,(A^e-\ensuremath\sqrt{2\gl} B^e).
\end{align*}
Observe that for $k$, $m\in\{1,\dotsc,n\}$ the matrix element $\ensuremath S^e_{km}(\lambda)$
of the scattering matrix is obtained from the resolvent kernel as
\begin{equation*}
    \ensuremath S^e_{km}(\lambda)
        = \ensuremath\sqrt{2\gl}\,\lim_{\xi,\,\eta\to v}\bigl(\ensuremath r^e_\lambda(\xi,\eta) - r_\lambda(\xi,\eta)\bigr),
\end{equation*}
where the limit on the right hand side is taken in such a way that $\xi$, $\eta$ converge
to $v$ along the edges $l_k$, $l_m$ respectively. $\ensuremath S^e_{km}(\lambda)$ in turn fixes the
data $w_m$ and $\beta$, e.g., via the behavior for large $\lambda$, that is from the behavior
at ``large energies''
\begin{equation*}
    w_m = \frac{1}{2}\bigl(\delta_{km} + \lim_{\lambda'\ensuremath\uparrow\infty} \ensuremath S^e_{km}(\lambda')\bigr),
            \quad \text{for all $k\in\ensuremath\{1,2,\dotsc,n\}$},
\end{equation*}
and
\begin{equation*}
    \beta = \ensuremath\sqrt{2\gl}\Bigl(\frac{\delta_{km}+\lim_{\lambda'\ensuremath\uparrow\infty}\ensuremath S^e_{km}(\lambda')}
            {\delta_{km}+\ensuremath S^e_{mm}(\lambda)}-1\Bigr),\quad \text{for all $\lambda$, and all $k$, $m\in\ensuremath\{1,2,\dotsc,n\}$}.
\end{equation*}
Alternatively, the data can be obtained from the small $\lambda$ behavior, that is the
threshold behavior, of the scattering matrix, since from
\begin{equation*}
    \frac{w_m}{\beta}
        = \lim_{\lambda \ensuremath\downarrow 0} \frac{1}{2\ensuremath\sqrt{2\gl}}\bigl(\ensuremath S^e_{km}(\lambda)+\delta_{km}\bigr)
            \qquad \text{for all $k\in\ensuremath\{1,2,\dotsc,n\}$},
\end{equation*}
we obtain
\begin{equation*}
    \beta^{-1} = \frac{1}{2\ensuremath\sqrt{2\gl}}\Bigl(\sum_{m=1}^n\ensuremath S^e_{km}(\lambda)+1\Bigr)
            \qquad \text{for all $k\in\ensuremath\{1,2,\dotsc,n\}$},
\end{equation*}
and therefore
\begin{equation*}
    w_m = \frac{\lim_{\lambda\ensuremath\downarrow 0} \lambda^{-1/2}\bigl(\ensuremath S^e_{km}(\lambda)+\delta_{km}\bigr)}
            {\lim_{\lambda\ensuremath\downarrow 0} \lambda^{-1/2}\Bigl(\sum_m\ensuremath S^e_{k'm}(\lambda)+1\Bigr)}
            \qquad \text{for all $k$, $k'\in\ensuremath\{1,2,\dotsc,n\}$}.
\end{equation*}

Furthermore we remark that in the context of quantum mechanics in the self-adjoint
case $w_k=1/n$, $\ensuremath k=1,\dotsc,n$, the boundary conditions of the elastic Walsh process are
interpreted as the presence of a $\delta$--potential of strength $\beta$ at the vertex.
\end{remark}

In order to compute expressions for the transition kernel of the elastic Walsh
process, we use the following two inverse Laplace transforms which follow from
formulae (5.3.4) and (5.6.12) in~\cite{ErMa54a} (cf.\ also appendix~C
in~\cite{BMMG0}) ($\lambda>0$, $t\ge 0$, $x\ge0$):
\begin{align}
    \frac{\ensuremath\sqrt{2\gl}}{\beta+\ensuremath\sqrt{2\gl}}\quad
        &\mathop{\longrightarrow}^{\mathcal{L}^{-1}}\quad
            \epsilon_0(dt) - \beta\Bigl(\frac{1}{\sqrt{2\pi t}}-\frac{\beta}{2}e^{\beta^2 t/2}
            \mathop{\operator@font erfc}\nolimits\Bigl(\beta\sqrt{\frac{t}{2}}\Bigr)\Bigr)\,dt,\label{eq3.7}\\
    \frac{1}{\beta+\ensuremath\sqrt{2\gl}}\,e^{-\ensuremath\sqrt{2\gl} x}\quad
        &\mathop{\longrightarrow}^{\mathcal{L}^{-1}}\quad
            g(t,x) - \frac{\beta}{2}\,e^{\beta x+ \beta^2 t/2}
            \mathop{\operator@font erfc}\nolimits\Bigl(\frac{x}{\sqrt{2t}}+\beta\sqrt{\frac{t}{2}}\Bigr).\label{eq3.8}
\end{align}
Then the inverse Laplace transform of the scattering matrix $\ensuremath S^e$ is given by
the following measures on $\mathbb{R}_+$:
\begin{equation}    \label{eq3.9}
 \begin{split}
    \ensuremath s^e_{km}(dt)
        = (2w_m-\delta_{km})\,\epsilon_0(dt) &- 2w_m\beta\,\frac{1}{\sqrt{2\pi t}}\,dt\\
        & + w_m\beta^2 e^{\beta^2t/2}\,\mathop{\operator@font erfc}\nolimits\Bigl(\beta\sqrt{\frac{t}{2}}\Bigr)\,dt,
\end{split}
\end{equation}
with $k$, $m\in\ensuremath\{1,2,\dotsc,n\}$. Moreover, for $t>0$, $x\ge 0$, let us introduce
\begin{equation}    \label{eq3.10}
    g_{\beta,0}(t,x) = g(t,x) - \frac{\beta}{2}\,e^{\beta x+ \beta^2 t/2}
            \mathop{\operator@font erfc}\nolimits\Bigl(\frac{x}{\sqrt{2t}}+\beta\sqrt{\frac{t}{2}}\Bigr).
\end{equation}

\begin{proof}
Let $W$, and therefore also $\ensuremath W^s$, start in the vertex $v$. Since $\ensuremath W^s$ and $W$
have continuous paths with infinite lifetime we have for all $\gamma\ge 0$
\begin{equation*}
    \ensuremath H^s_{v,\epsilon} = \inf\bigl\{t>0,\, d(v,W_{\tau(t)})=\epsilon\bigr\},
\end{equation*}
and in particular for $\gamma=0$,
\begin{equation*}
    \ensuremath H^w_{v,\epsilon} = \inf\bigl\{t>0,\, d(v,W_t)=\epsilon\bigr\}.
\end{equation*}
Moreover, as argued above, both infima are a.s.\ finite. Set
\begin{equation*}
    \sigma = \ensuremath H^w_{v,\epsilon} + \gamma\,L^w_{\ensuremath H^w_{v,\epsilon}}.
\end{equation*}
Then $\tau(\sigma) = \ensuremath H^w_{v,\epsilon}$, and therefore
\begin{align*}
    d\bigl(v, \ensuremath W^s_\sigma\bigr)
        &= d\bigl(v, W_{\tau(\sigma)}\bigr)\\
        &= d\bigl(v, W_{\ensuremath H^w_{v,\epsilon}}\bigr)\\
        &= \epsilon.
\end{align*}
Consequently we get $\ensuremath H^s_{v,\epsilon} \le \sigma$. To derive the converse inequality
we remark that
\begin{align*}
    \epsilon
        &= d\bigl(v, \ensuremath W^s_{\ensuremath H^s_{v,\epsilon}}\bigr)\\
        &= d\bigl(v, W_{\tau(\ensuremath H^s_{v,\epsilon})}\bigr),
\end{align*}
which implies
\begin{equation*}
    \tau\bigl(\ensuremath H^s_{v,\epsilon}\bigr)\ge \ensuremath H^w_{v,\epsilon}.
\end{equation*}
Since $\tau$ is strictly increasing this entails
\begin{equation*}
    \ensuremath H^s_{v,\epsilon} \ge \tau^{-1}\bigl(\ensuremath H^w_{v,\epsilon}\bigr) = \sigma,
\end{equation*}
and the proof is finished.
\end{proof}

\begin{proof}
Let $A^s$ be the generator of $\ensuremath W^s$ on $\ensuremath C_0(\cG)$. From the identity $A^s \ensuremath R^s_\lambda =
\lambda\,\ensuremath R^s_\lambda -\text{id}$, and the definition of $\tau$ we get
\begin{align*}
    \frac{1}{2}\,\bigl(\ensuremath R^s_\lambda f\bigr)''(v)
        &= \lambda E_v\Bigl(\int_0^\infty e^{-\lambda t}\bigl(f(\ensuremath W^s_t)-f(v)\bigr)\,dt\Bigr)\\
        &= \lambda E_v\Bigl(\int_0^\infty e^{-\lambda(s+\gamma L^w_s)}
            \bigl(f(W_s)-f(v)\bigr)\,(ds + \gamma dL^w_s)\Bigr)\\
        &= \lambda E_v\Bigl(\int_0^\infty e^{-\lambda(s+\gamma L^w_s)}
            \bigl(f(W_s)-f(v)\bigr)\,ds \Bigr).
\end{align*}
In the last equality we used the fact that $L^w$ only grows when $W$ is at the vertex~$v$.
By construction of the Walsh process $W$ we have
\begin{align*}
    E_v\Bigl(&e^{-\lambda\gamma L^w_s}\bigl(f(W_s)-f(v)\bigr)\Bigr)\\
        &= \sum_{k=1}^n w_k\,E_0\Bigl(e^{-\lambda\gamma L^B_s}
                \bigl(f_k(|B_s|) - f_k(0)\bigr) \Bigr)\\
        &= 2\sum_{k=1}^n w_k \int_0^\infty \int_0^\infty e^{-\lambda\gamma y}
                \bigl(f_k(x) - f_k(0)\bigr)\,\frac{x+y}{\sqrt{2\pi s^3}}\,
                    e^{-(x+y)^2/2s}\,dx\,dy,
\end{align*}
where we used lemma~\ref{lem1.1}. We insert the last expression above, and
use formula~\eqref{LT}. This gives
\begin{align*}
    \frac{1}{2}\,\bigl(\ensuremath R^s_\lambda f\bigr)''(v)
        &= 2\lambda \sum_{k=1}^n w_k\,\frac{1}{\ensuremath\sqrt{2\gl} + \gamma\lambda}\,
            \int_0^\infty e^{-\ensuremath\sqrt{2\gl} x}\bigl(f_k(x)-f_k(0)\bigr)\,dx\\
        &= \frac{1}{\ensuremath\sqrt{2\gl}+\gamma\lambda}\,\bigl(2\lambda\,(e^w_\lambda,f) - \ensuremath\sqrt{2\gl} f(v)\bigr). \qedhere
\end{align*}
\end{proof}

From the identity $A^s \ensuremath R^s_\lambda = \lambda\,\ensuremath R^s_\lambda -\text{id}$ and some simple
algebra we get the

\begin{remark}
When all $w_m$, $m=1$, \dots, $n$, are equal to $1/n$, the matrix $S^s(\lambda)$ takes the
form
\begin{equation*}
	S^s(\lambda) = -\1 + \frac{2\ensuremath\sqrt{2\gl}}{\ensuremath\sqrt{2\gl} + \gamma \lambda}\,P_n
\end{equation*}
which reduces to~\eqref{eq2.6a} when $\gamma=0$. $S^s(\lambda)$ is unitary for all $\lambda<0$.
Also the $S^s(\lambda)$ for different $\lambda$ all commute. As a consequence $S^s(\lambda)$
has the interpretation of a quantum scattering matrix in the sense of~\cite{KoSc99}.
More precisely, $S^s(\lambda)$ stems from the Schr\"odinger operator $-\Delta^s$, where
$\Delta^s$ is a self-adjoint Laplace operator on $L^2(\mathcal{G})$ with boundary conditions
of the form~\eqref{bc} with the choice
\begin{equation}		\label{AB}
\begin{split}
	A &= - \frac{1}{2}\,\bigl(S^s(\lambda_0)+\1\bigr),\\
	B &= - \frac{1}{2\sqrt{\mathstrut2\lambda_0}}\,\bigl(S^s(\lambda_0)-\1\bigr),
\end{split}
\end{equation}
for any $\lambda_0$ for which $\sqrt{2\lambda_0}+\gamma\lambda_0\ne 0$. We emphasize that
the Schr\"odinger operator $-\Delta^s$ and the generator $A^s$ of the Walsh process
are quite different: Not only do they act on different Banach spaces,
but also the functions in the intersection of their domains satisfy different
boundary conditions at the vertex $v$. As matter of fact, the integral kernel
of the resolvent  $(-\Delta^s+2\lambda)^{-1}$ of the Schr\"odinger operator $-\Delta^s$ is
given by, see Lemma~4.2 in~\cite{KoSc06},
\begin{equation*}
 \frac{1}{2}\Bigl(r_\lambda(\xi,\eta)
            +\sum_{k,m=1}^n e_{\lambda,k}(\xi)\,
				\ensuremath S^s_{km}(\lambda)\,\frac{1}{\ensuremath\sqrt{2\gl}}\,e_{\lambda,m}(\eta)\Bigl),
\end{equation*}
that is --- up to a factor $2$ --- by the right hand side of~\eqref{eq4.14a}
\emph{without} the last term.

In more detail and with the definition~\eqref{SE}
\begin{equation*}
	S_{A,B}\bigl(E=-2\lambda\bigr) = S^s(\lambda)
\end{equation*}
holds for all $\lambda>0$. As a function of $k$ ($k^2=E$), $S^s$ is meromorphic in the complex $k$--plane with
a pole on the positive imaginary axis at $k^b=2i/\gamma$. This corresponds to a negative
eigenvalue $E^b=-4/\gamma^2$ of $-\Delta^s$. The corresponding (normalized) eigenfunction
$\psi^b$ --- physically speaking a \emph{bound state} --- is given as
\begin{equation*}
	\psi^b(\xi) = \frac{1}{2}\,\sqrt{\frac{\gamma}{n}}\,e^{-2 d(v,\xi)/\gamma},\qquad \xi\in\mathcal{G}.
\end{equation*}
So quantum mechanically the vertex $v$ acts like an attractive potential. We view this
as a quantum analogue of the stickiness of the vertex $v$.

This analogy can be elaborated a bit further by inspecting the associated quantum mechanical
time delay matrix (see, e.g., \cite{AmJa77, BrFr02, JaMi72, Ma76, Ma81, Na80, Wi55})
\begin{equation*}
	T(k) = \frac{1}{2ik}\,S(k)^{-1}\frac{\partial}{\partial k} S(k)
\end{equation*}
which in the present context gives
\begin{equation*}
	T(k) = \frac{-2\gamma}{k(4+k^2\gamma^2)}\,P_n.
\end{equation*}
So $T(k)$ has zero as an $(n-1)$--fold eigenvalue plus the non-degenerate
eigenvalue
\begin{equation*}
	\frac{-2\gamma}{k(4+k^2\gamma^2)},
\end{equation*}
which for $\gamma>0$ is the signal for a strict quantum delay. Observe that for
$k\to +\infty$, that is for large energies, the time delay experienced by the
quantum particle tends to zero, while for $k\to 0$, i.e., for low energies,
the delay becomes arbitrarily large. From the physical point of view, both
effects are clearly to be expected. For comparison and in contrast to the
present stochastic context, in quantum mechanics $\gamma<0$ is also allowed for a
meaningful Schr\"odinger operator and an associated scattering matrix.

\end{remark}

Define for $x\ge 0$, $\gamma$, $t>0$,
\begin{equation}    \label{eq4.15}
    g_{0,\gamma}(t,x) = \frac{1}{\gamma}\,\exp\Bigl(\frac{2x}{\gamma} + \frac{2t}{\gamma^2}\Bigr)\,
                    \mathop{\operator@font erfc}\nolimits\Bigl(\frac{x}{\sqrt{2t}}+\frac{\sqrt{2t}}{\gamma}\Bigr).
\end{equation}
It is not hard to check that
\begin{equation}	\label{lim_g}
    \lim_{\gamma\downarrow 0} g_{0,\gamma}(t,x) = g(t,x) = \frac{1}{\sqrt{2\pi t}}\,e^{-x^2/2t}.
\end{equation}
Moreover, from~\cite[eq.~(5.6.16)]{ErMa54a} (cf.\ also appendix~C
in~\cite{BMMG0}) the Laplace transform is
\begin{equation}    \label{eq4.16}
    \mathcal{L} g_{0,\gamma}(\,\cdot\,,x)(\lambda) = \frac{1}{\ensuremath\sqrt{2\gl} + \gamma\lambda}\,e^{-\ensuremath\sqrt{2\gl} x},\qquad x\ge 0.
\end{equation}
Observe that in agreement with~\eqref{lim_g}
\begin{equation*}
	\mathcal{L} g(\,\cdot\,,x)(\lambda) = \frac{1}{\ensuremath\sqrt{2\gl}}\,e^{-\ensuremath\sqrt{2\gl} x}
\end{equation*}
holds. Now we can readily compute the inverse Laplace transform of formulae~\eqref{eq4.13},
\eqref{eq4.14}, and obtain the following result.

\begin{proof}
For $\gamma$, $r\in\mathbb{R}_+$ define the random subset
\begin{equation*}
    J_\gamma(r) = \{t\ge 0,\, L^s_t>r\}
\end{equation*}
of $\mathbb{R}_+$. Since $L^s$ is pathwise increasing, this set is a random interval
with endpoints $K^s_r$ and $+\infty$. The relation $L^s_{K^s_r}=r$
implies that
\begin{equation*}
	J_\gamma(r) = (K^s_r,+\infty).
\end{equation*}
In particular, we have $J_0 = (K^w_r,+\infty)$. Now
\begin{equation*}
    t\in J_\gamma(r) \Leftrightarrow L^s_t = L^w_{\tau(t)} > r \Leftrightarrow \tau(t)\in J_0(r).
\end{equation*}
In other words, $J_\gamma(r) = \tau^{-1}\bigl(J_0(r))$, and therefore
$K^s_r=\tau^{-1}(K^w_r)$ holds. From the definition of $\tau^{-1}$ (see equation~\eqref{eq4.1}),
and the relation  $L^s_{K^s_r}=r$ we obtain formula~\eqref{eq5.1a}
\end{proof}

